package locale

// Japanese translations for engine/planner/worker/deadline timeline and log
// messages (see server_engine.go). These appear in the task timeline and the
// System logs page. Log prefixes ([planner], [worker %s], …), state tokens
// (exhausted/stopped/done/model_error), and format verbs are preserved.
