	RegisterJa("fk_violation(23503,parent exploration missing)", "fk_violation(23503,親の探索が存在しません)")
	RegisterJa("%w: intent %d has no running worker (it may have finished or not yet been claimed)", "%w: 意図 %d に実行中のワーカーがありません（完了したか、まだクレームされていない可能性があります）")
	RegisterJa("%w: intent %d is undergoing %s", "%w: 意図 %d は %s を処理中です")
	RegisterJa("Wait for intent %d to finish %s: %w", "意図 %d の %s の完了を待機: %w")
	RegisterJa("%w: intent %d is no longer in state %s", "%w: 意図 %d はもう %s 状態ではありません")
	RegisterJa("Steering message cannot be empty", "誘導メッセージを空にはできません")
